import { Component, DoCheck, Input, ElementRef, Inject, IterableDiffers, IterableDiffer, NgModule } from '@angular/core';

import { RadCalendar } from 'nativescript-ui-calendar';
import { View, Page, ObservableArray } from '@nativescript/core';
import { registerElement } from '@nativescript/angular';

@Component({
	selector: 'RadCalendar',
	template: ''
})
export class RadCalendarComponent implements DoCheck {
	private _calendar: RadCalendar;
	private _eventSource: any;
	private _differ: IterableDiffer<any>;
	private timerId: number;
	private doCheckDelay = 5;

	constructor(@Inject(ElementRef) private _elementRef: ElementRef, @Inject(IterableDiffers) private _iterableDiffers: IterableDiffers) {
		this._calendar = _elementRef.nativeElement;
	}

	@Input() set eventSource(value: any) {
		this._eventSource = value;
		let needDiffer = true;
		if (value instanceof ObservableArray) {
			needDiffer = false;
		}

		if (needDiffer && !this._differ && CollectionUtils.isListLikeIterable(value)) {
			this._differ = this._iterableDiffers.find(this._eventSource).create((index, item) => item);
		}

		this._calendar.eventSource = this._eventSource;
	}

	public get nativeElement(): RadCalendar {
		return this._calendar;
	}

	public get calendar() {
		return this._calendar;
	}

	ngDoCheck() {
		if (this._differ) {
			let changes = this._differ.diff(this._eventSource);
			if (changes) {
				this._calendar.reload();
			}
		}
	}
}

