// Copied from angular 2 @angular/common/src/facade/collection
namespace CollectionUtils {
	interface BrowserNodeGlobal {
		Object: typeof Object;
		Array: typeof Array;
		Map: typeof Map;
		Set: typeof Set;
		Date: DateConstructor;
		RegExp: RegExpConstructor;
		JSON: typeof JSON;
		Math: any; // typeof Math;
		assert(condition: any): void;
		Reflect: any;
		getAngularTestability: Function;
		getAllAngularTestabilities: Function;
		getAllAngularRootElements: Function;
		frameworkStabilizers: Array<Function>;
		setTimeout: Function;
		clearTimeout: Function;
		setInterval: Function;
		clearInterval: Function;
		encodeURI: Function;
	}

	function isPresent(obj: any): boolean {
		return obj !== undefined && obj !== null;
	}

	function isBlank(obj: any): boolean {
		return obj === undefined || obj === null;
	}

	declare var Symbol: any;
	let _symbolIterator: any = null;
	let globalScope: BrowserNodeGlobal;

	function getSymbolIterator(): string | symbol {
		if (isBlank(_symbolIterator)) {
			if (isPresent((<any>globalScope).Symbol) && isPresent(Symbol.iterator)) {
				_symbolIterator = Symbol.iterator;
			} else {
				// es6-shim specific logic
				const keys = Object.getOwnPropertyNames(Map.prototype);
				for (let i = 0; i < keys.length; ++i) {
					const key = keys[i];
					if (key !== 'entries' && key !== 'size' && (Map as any).prototype[key] === Map.prototype['entries']) {
						_symbolIterator = key;
					}
				}
			}
		}
		return _symbolIterator;
	}

	function isJsObject(o: any): boolean {
		return o !== null && (typeof o === 'function' || typeof o === 'object');
	}

	function isArray(obj: any): boolean {
		return Array.isArray(obj);
	}

	export function isListLikeIterable(obj: any): boolean {
		if (!isJsObject(obj)) return false;
		return (
			isArray(obj) ||
			(!(obj instanceof Map) && // JS Map are iterables but return entries as [k, v]
				getSymbolIterator() in obj)
		); // JS Iterable have a Symbol.iterator prop
	}
}
