export const CALENDAR_DIRECTIVES = [RadCalendarComponent];
registerElement('RadCalendar', () => RadCalendar);

@NgModule({
	declarations: [CALENDAR_DIRECTIVES],
	exports: [CALENDAR_DIRECTIVES]
})
export class NativeScriptUICalendarModule {}
